import { useState } from 'react'
import { Leaf, LogIn } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { login } from '../api/auth'
import { decodeToken } from '../auth/auth'

const destinations = { resident: '/resident', rwa: '/rwa', gcc: '/gcc', admin: '/admin' }
export default function Login() {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [loading, setLoading] = useState(false); const navigate = useNavigate()
  const submit = async (event) => { event.preventDefault(); setError(''); setLoading(true); try { const { access_token } = await login({ username, password }); const claims = decodeToken(access_token); if (!claims?.role) throw new Error('Invalid access token'); localStorage.setItem('smartseg_token', access_token); localStorage.setItem('smartseg_role', claims.role); navigate(destinations[claims.role] || '/login', { replace: true }) } catch (err) { setError(err.response?.data?.detail || 'We could not sign you in. Check your credentials.') } finally { setLoading(false) } }
  return <main className="grid min-h-screen place-items-center bg-cream p-5"><section className="grid w-full max-w-4xl overflow-hidden border border-line bg-paper shadow-paper md:grid-cols-[.9fr_1.1fr]"><div className="bg-forest p-8 text-paper md:p-12"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center bg-terracotta"><Leaf size={22}/></span><span className="font-display text-2xl">SmartSeg</span></div><h1 className="mt-16 font-display text-4xl leading-tight">Waste, made visible.</h1><p className="mt-4 max-w-xs text-sm leading-6 text-[#dce5da]">A grounded local system for cleaner bins, fairer rewards, and a healthier neighbourhood.</p></div><form onSubmit={submit} className="p-8 md:p-12"><p className="text-xs font-bold uppercase tracking-[.16em] text-terracotta">Secure access</p><h2 className="mt-2 text-3xl text-forest">Welcome back</h2><label className="mt-8 block text-sm font-semibold">Username<input value={username} onChange={(e)=>setUsername(e.target.value)} required className="mt-2 w-full border border-line bg-cream px-3 py-3 outline-none focus:border-forest"/></label><label className="mt-5 block text-sm font-semibold">Password<input type="password" value={password} onChange={(e)=>setPassword(e.target.value)} required className="mt-2 w-full border border-line bg-cream px-3 py-3 outline-none focus:border-forest"/></label>{error && <p className="mt-4 border-l-4 border-clay bg-[#fff2ed] p-3 text-sm text-clay">{error}</p>}<button disabled={loading} className="mt-7 flex w-full items-center justify-center gap-2 bg-terracotta px-4 py-3 font-bold text-paper hover:bg-clay disabled:opacity-60"><LogIn size={17}/>{loading ? 'Signing in…' : 'Sign in'}</button></form></section></main>
}
